// read a tree in level order; -1 means "no child"
TreeNode* readTree() {
    int x; cin >> x;
    if (x == -1) return nullptr;
    TreeNode* root = new TreeNode(x);
    queue<TreeNode*> q; q.push(root);
    while (!q.empty()) {
        TreeNode* cur = q.front(); q.pop();
        int l, r; cin >> l >> r;
        if (l != -1) { cur->left = new TreeNode(l); q.push(cur->left); }
        if (r != -1) { cur->right = new TreeNode(r); q.push(cur->right); }
    }
    return root;
}
int main() {
    TreeNode* root = readTree();
    int low, high; cin >> low >> high;
    cout << "rangeSumBST = " << Solution().rangeSumBST(root, low, high) << endl;
}

